package com.example.english_app;
import android.app.Activity;import android.content.Intent;import android.os.Bundle;import android.graphics.Color;import android.graphics.drawable.GradientDrawable;import android.view.View;import android.view.animation.DecelerateInterpolator;import android.widget.LinearLayout;import android.widget.TextView;
public class VocabularyActivity extends Activity {
private int index=0;private TextView counter,title,meaning,ipa,example,dialogue,usage,next;private LinearLayout segments;private final String[] words={"Discretionary spending","Household budget","Financial literacy","To tighten one's belt","Emergency fund","Expenditure","Living paycheck to paycheck"};
private final String[] meanings={"Chi tiêu tùy ý","Ngân sách hộ gia đình","Kiến thức tài chính","Thắt chặt chi tiêu","Quỹ khẩn cấp","Khoản chi tiêu","Sống phụ thuộc vào từng kỳ lương"};
private final String[] ipas={"/dɪˈskreʃəneri ˈspendɪŋ/","/ˈhaʊshoʊld ˈbʌdʒɪt/","/faɪˈnænʃəl ˈlɪtərəsi/","/tə ˈtaɪtən wʌnz belt/","/ɪˈmɜːrdʒənsi fʌnd/","/ɪkˈspendɪtʃər/","/ˈlɪvɪŋ ˈpeɪtʃek tə ˈpeɪtʃek/"};
private final String[] examples={"I want to cut my discretionary spending this month.","We need to make a household budget.","Financial literacy helps people manage money.","We must tighten our belts this month.","She has an emergency fund.","They reduced their monthly expenditure.","He is living paycheck to paycheck."};
@Override public void onCreate(Bundle state){super.onCreate(state);setContentView(R.layout.activity_vocabulary);counter=findViewById(R.id.vocabCounter);title=findViewById(R.id.wordTitle);meaning=findViewById(R.id.wordMeaning);ipa=findViewById(R.id.wordIpa);example=findViewById(R.id.wordExample);dialogue=findViewById(R.id.wordDialogue);usage=findViewById(R.id.wordUsage);next=findViewById(R.id.vocabNext);segments=findViewById(R.id.progressSegments);findViewById(R.id.vocabBack).setOnClickListener(v->finish());next.setOnClickListener(v->{if(index<words.length-1){index++;render(true);}else {LearningProgress.markFinanceVocabularyDone(this);Intent home=new Intent(this,HomeActivity.class);home.addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_SINGLE_TOP);startActivity(home);finish();}});ipa.setOnClickListener(v->StateScreensActivity.open(this,"vocab_audio_error"));render(false);}
private void render(boolean animate){counter.setText("TỪ "+(index+1)+" TRONG 7");title.setText(words[index]);meaning.setText(meanings[index]);ipa.setText(ipas[index]+"    ▶ Phát audio");example.setText(examples[index]);dialogue.setText("A: How can we save more?\nB: Let's review our monthly expenses.");usage.setText("Diễn đạt một kế hoạch chi tiêu thực tế trong cuộc sống.");next.setText(index==words.length-1?"Hoàn tất":"Tiếp tục");segments.removeAllViews();float density=getResources().getDisplayMetrics().density;for(int i=0;i<7;i++){View bar=new View(this);GradientDrawable bg=new GradientDrawable();bg.setCornerRadius(20*density);bg.setColor(Color.parseColor(i<index?"#77E4C2":i==index?"#F8C957":"#445074"));bar.setBackground(bg);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,(int)(6*density),1);lp.setMargins(0,0,i==6?0:(int)(5*density),0);segments.addView(bar,lp);}if(animate){int[] ids={R.id.vocabCounter,R.id.progressSegments,R.id.wordTitle,R.id.wordMeaning,R.id.sectionPronunciation,R.id.sectionExample,R.id.sectionDialogue,R.id.sectionUsage,R.id.vocabNext};boolean reduce=android.provider.Settings.Global.getFloat(getContentResolver(),android.provider.Settings.Global.ANIMATOR_DURATION_SCALE,1f)==0f;if(!reduce)for(int i=0;i<ids.length;i++){View v=findViewById(ids[i]);v.animate().cancel();v.setAlpha(0f);v.setTranslationY(16*density);v.animate().alpha(1).translationY(0).setStartDelay(i*130L).setDuration(350).setInterpolator(new DecelerateInterpolator()).start();}}}
}
